import os
import csv
import json
import random

import numpy as np
import matplotlib.pyplot as plt

from sklearn.metrics import (
    confusion_matrix,
    roc_auc_score,
    average_precision_score,
)


# ============================================================
# PATHS
# ============================================================

EXPERIMENT_NAME = "EXP_01_DMR_Multiview_ResNet18"

RESULTS_DIR = (
    r"D:\HITEC\STUDENT\NEW PROJECT\Breast_Thermography"
    r"\Experiments\Multi_View\EXP_01_DMR_Multiview_ResNet18"
    r"\Results"
)

# OOF predictions generated by Run 04
RUN_04_NAME = "Run_04_5-fold_CV_OOF_Predictions"

RUN_04_DIR = os.path.join(
    RESULTS_DIR,
    RUN_04_NAME,
)

OOF_FILE = os.path.join(
    RUN_04_DIR,
    "oof_predictions.csv",
)

# Current run
RUN_NAME = "Run_05_OOF_Threshold_Selection"

RUN_DIR = os.path.join(
    RESULTS_DIR,
    RUN_NAME,
)

RESULTS_OUTPUT_DIR = os.path.join(
    RUN_DIR,
    "results",
)

PLOT_DIR = os.path.join(
    RUN_DIR,
    "plots",
)

os.makedirs(
    RESULTS_OUTPUT_DIR,
    exist_ok=True,
)

os.makedirs(
    PLOT_DIR,
    exist_ok=True,
)


# ============================================================
# THRESHOLD SELECTION SETTINGS
# ============================================================

MIN_SENSITIVITY = 0.91
MIN_SPECIFICITY = 0.60

SEED = 10

FIXED_EPOCH = 82
EXPECTED_OOF_COUNT = 165
EXPECTED_HEALTHY = 101
EXPECTED_SICK = 64
EXPECTED_FOLDS = 5


# ============================================================
# PRINT CONFIGURATION
# ============================================================

print(
    "\nExperiment:",
    EXPERIMENT_NAME,
)

print("Run:", RUN_NAME)
print("Input:", OOF_FILE)
print("Fusion head: A - Baseline")
print("Fixed epoch:", FIXED_EPOCH)

print(
    "Required sensitivity: >",
    MIN_SENSITIVITY,
)

print(
    "Required specificity: >",
    MIN_SPECIFICITY,
)

print(
    "Selection criterion:",
    "Highest sensitivity",
)

print(
    "Tie-breaker:",
    "Highest specificity",
)

print(
    "Final tie-breaker:",
    "Highest threshold",
)

print("Model training: NOT PERFORMED")
print("Test set: NOT USED")


# ============================================================
# REPRODUCIBILITY
# ============================================================

random.seed(SEED)
np.random.seed(SEED)

try:
    import torch

    torch.manual_seed(SEED)

    if torch.cuda.is_available():
        torch.cuda.manual_seed(SEED)
        torch.cuda.manual_seed_all(SEED)

    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False

except ImportError:
    pass


# ============================================================
# LOAD OOF PREDICTIONS
# ============================================================

if not os.path.exists(OOF_FILE):
    raise FileNotFoundError(
        f"OOF prediction file not found:\n{OOF_FILE}"
    )


patient_ids = []
true_labels = []
oof_probabilities = []
oof_folds = []


with open(
    OOF_FILE,
    "r",
    newline="",
    encoding="utf-8",
) as f:

    reader = csv.DictReader(f)

    required_columns = {
        "patient_id",
        "true_label",
        "oof_fold",
        "oof_probability",
    }

    if reader.fieldnames is None:
        raise ValueError(
            "OOF prediction file does not contain a header."
        )

    missing_columns = (
        required_columns
        - set(reader.fieldnames)
    )

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            f"{sorted(missing_columns)}"
        )

    for row in reader:

        patient_ids.append(
            row["patient_id"]
        )

        true_labels.append(
            int(row["true_label"])
        )

        oof_folds.append(
            int(row["oof_fold"])
        )

        oof_probabilities.append(
            float(row["oof_probability"])
        )


y_true = np.asarray(
    true_labels,
    dtype=np.int32,
)

y_probability = np.asarray(
    oof_probabilities,
    dtype=np.float64,
)

oof_folds = np.asarray(
    oof_folds,
    dtype=np.int32,
)


# ============================================================
# INPUT VALIDATION
# ============================================================

if len(y_true) != EXPECTED_OOF_COUNT:
    raise ValueError(
        f"Expected {EXPECTED_OOF_COUNT} OOF predictions, "
        f"found {len(y_true)}."
    )

if len(y_probability) != len(y_true):
    raise ValueError(
        "Number of probabilities does not match "
        "number of labels."
    )

if len(oof_folds) != len(y_true):
    raise ValueError(
        "Number of fold assignments does not match "
        "number of predictions."
    )

if len(patient_ids) != len(y_true):
    raise ValueError(
        "Number of patient IDs does not match "
        "number of predictions."
    )

if len(set(patient_ids)) != len(patient_ids):
    raise ValueError(
        "Duplicate patient IDs found in OOF predictions."
    )

if any(
    not patient_id.strip()
    for patient_id in patient_ids
):
    raise ValueError(
        "Empty patient ID detected."
    )

if np.any(~np.isfinite(y_probability)):
    raise ValueError(
        "OOF probabilities contain NaN or infinite values."
    )

if (
    np.any(y_probability < 0.0)
    or np.any(y_probability > 1.0)
):
    raise ValueError(
        "OOF probabilities must be between 0 and 1."
    )

if set(np.unique(y_true)) != {0, 1}:
    raise ValueError(
        "Expected binary labels {0, 1}."
    )

if len(np.unique(oof_folds)) != EXPECTED_FOLDS:
    raise ValueError(
        f"Expected {EXPECTED_FOLDS} OOF folds."
    )

if set(np.unique(oof_folds)) != set(
    range(1, EXPECTED_FOLDS + 1)
):
    raise ValueError(
        "Invalid OOF fold assignments detected."
    )

for fold in range(1, EXPECTED_FOLDS + 1):

    fold_count = int(
        np.sum(oof_folds == fold)
    )

    if fold_count != 33:
        raise ValueError(
            f"Fold {fold}: expected 33 predictions, "
            f"found {fold_count}."
        )

if int(np.sum(y_true == 0)) != EXPECTED_HEALTHY:
    raise ValueError(
        "Unexpected number of Healthy patients."
    )

if int(np.sum(y_true == 1)) != EXPECTED_SICK:
    raise ValueError(
        "Unexpected number of Sick patients."
    )


# ============================================================
# OOF SUMMARY
# ============================================================

overall_oof_roc_auc = roc_auc_score(
    y_true,
    y_probability,
)

overall_oof_pr_auc = average_precision_score(
    y_true,
    y_probability,
)

print(
    "\nOOF predictions loaded:",
    len(y_true),
)

print(
    "Healthy:",
    np.sum(y_true == 0),
)

print(
    "Sick:",
    np.sum(y_true == 1),
)

print(
    "Folds:",
    sorted(
        np.unique(oof_folds).tolist()
    ),
)

print(
    "Overall OOF ROC-AUC:",
    overall_oof_roc_auc,
)

print(
    "Overall OOF PR-AUC:",
    overall_oof_pr_auc,
)


# ============================================================
# THRESHOLD VALUES
# ============================================================

# Evaluate every unique OOF probability.
thresholds = np.unique(
    y_probability
)

threshold_results = []


# ============================================================
# EVALUATE EACH THRESHOLD
# ============================================================

for threshold in thresholds:

    y_pred = (
        y_probability >= threshold
    ).astype(np.int32)

    tn, fp, fn, tp = confusion_matrix(
        y_true,
        y_pred,
        labels=[0, 1],
    ).ravel()

    sensitivity = (
        tp / (tp + fn)
        if (tp + fn) > 0
        else 0.0
    )

    specificity = (
        tn / (tn + fp)
        if (tn + fp) > 0
        else 0.0
    )

    accuracy = (
        (tp + tn)
        / len(y_true)
    )

    balanced_accuracy = (
        sensitivity + specificity
    ) / 2.0

    precision = (
        tp / (tp + fp)
        if (tp + fp) > 0
        else 0.0
    )

    f1 = (
        2
        * precision
        * sensitivity
        / (precision + sensitivity)
        if (precision + sensitivity) > 0
        else 0.0
    )

    meets_constraints = (
        sensitivity > MIN_SENSITIVITY
        and
        specificity > MIN_SPECIFICITY
    )

    threshold_results.append(
        {
            "threshold": float(threshold),
            "sensitivity": float(sensitivity),
            "specificity": float(specificity),
            "accuracy": float(accuracy),
            "balanced_accuracy": float(
                balanced_accuracy
            ),
            "precision": float(precision),
            "f1": float(f1),
            "tn": int(tn),
            "fp": int(fp),
            "fn": int(fn),
            "tp": int(tp),
            "meets_constraints": bool(
                meets_constraints
            ),
        }
    )


# ============================================================
# FIND VALID THRESHOLDS
# ============================================================

valid_results = [
    result
    for result in threshold_results
    if result["meets_constraints"]
]


print(
    "\nValid thresholds:",
    len(valid_results),
)


# ============================================================
# SELECT THRESHOLD
# ============================================================

if not valid_results:

    # Save the full threshold analysis before reporting failure.
    threshold_csv = os.path.join(
        RESULTS_OUTPUT_DIR,
        "threshold_analysis.csv",
    )

    with open(
        threshold_csv,
        "w",
        newline="",
        encoding="utf-8",
    ) as f:

        writer = csv.DictWriter(
            f,
            fieldnames=list(
                threshold_results[0].keys()
            ),
        )

        writer.writeheader()
        writer.writerows(threshold_results)

    raise RuntimeError(
        "No threshold satisfies both conditions:\n"
        f"Sensitivity > {MIN_SENSITIVITY}\n"
        f"Specificity > {MIN_SPECIFICITY}\n"
        f"Threshold analysis saved to: {threshold_csv}"
    )


# Highest sensitivity.
# If tied, highest specificity.
# If still tied, highest threshold.

selected_result = max(
    valid_results,
    key=lambda x: (
        x["sensitivity"],
        x["specificity"],
        x["threshold"],
    ),
)

selected_threshold = (
    selected_result["threshold"]
)


# ============================================================
# PRINT SELECTED THRESHOLD
# ============================================================

print("\nSELECTED THRESHOLD")

print(
    f"Threshold:          "
    f"{selected_threshold:.6f}"
)

print(
    f"Sensitivity:        "
    f"{selected_result['sensitivity']:.4f}"
)

print(
    f"Specificity:        "
    f"{selected_result['specificity']:.4f}"
)

print(
    f"Accuracy:           "
    f"{selected_result['accuracy']:.4f}"
)

print(
    f"Balanced accuracy:  "
    f"{selected_result['balanced_accuracy']:.4f}"
)

print(
    f"Precision:          "
    f"{selected_result['precision']:.4f}"
)

print(
    f"F1-score:           "
    f"{selected_result['f1']:.4f}"
)

print(
    f"TN: {selected_result['tn']}  "
    f"FP: {selected_result['fp']}  "
    f"FN: {selected_result['fn']}  "
    f"TP: {selected_result['tp']}"
)


# ============================================================
# SAVE ALL THRESHOLD RESULTS
# ============================================================

threshold_csv = os.path.join(
    RESULTS_OUTPUT_DIR,
    "threshold_analysis.csv",
)

fieldnames = [
    "threshold",
    "sensitivity",
    "specificity",
    "accuracy",
    "balanced_accuracy",
    "precision",
    "f1",
    "tn",
    "fp",
    "fn",
    "tp",
    "meets_constraints",
]


with open(
    threshold_csv,
    "w",
    newline="",
    encoding="utf-8",
) as f:

    writer = csv.DictWriter(
        f,
        fieldnames=fieldnames,
    )

    writer.writeheader()

    writer.writerows(
        threshold_results
    )


# ============================================================
# SAVE SELECTED THRESHOLD
# ============================================================

selected_threshold_file = os.path.join(
    RESULTS_OUTPUT_DIR,
    "selected_threshold.json",
)

selected_threshold_data = {
    "experiment": EXPERIMENT_NAME,
    "run": RUN_NAME,
    "input_run": RUN_04_NAME,
    "fusion_head": "A - Baseline",
    "fixed_epoch": FIXED_EPOCH,
    "selection_method": (
        "Constraint-based threshold selection "
        "from OOF predictions"
    ),
    "constraints": {
        "sensitivity": (
            f">{MIN_SENSITIVITY}"
        ),
        "specificity": (
            f">{MIN_SPECIFICITY}"
        ),
    },
    "selection_criterion": (
        "Highest sensitivity among thresholds "
        "satisfying both constraints"
    ),
    "tie_breaker": (
        "Highest specificity"
    ),
    "final_tie_breaker": (
        "Highest threshold"
    ),
    "selected_threshold": float(
        selected_threshold
    ),
    "sensitivity": float(
        selected_result["sensitivity"]
    ),
    "specificity": float(
        selected_result["specificity"]
    ),
    "accuracy": float(
        selected_result["accuracy"]
    ),
    "balanced_accuracy": float(
        selected_result["balanced_accuracy"]
    ),
    "precision": float(
        selected_result["precision"]
    ),
    "f1": float(
        selected_result["f1"]
    ),
    "tn": int(
        selected_result["tn"]
    ),
    "fp": int(
        selected_result["fp"]
    ),
    "fn": int(
        selected_result["fn"]
    ),
    "tp": int(
        selected_result["tp"]
    ),
    "number_of_oof_predictions": int(
        len(y_true)
    ),
    "overall_oof_roc_auc": float(
        overall_oof_roc_auc
    ),
    "overall_oof_pr_auc": float(
        overall_oof_pr_auc
    ),
    "test_set_used": False,
}


with open(
    selected_threshold_file,
    "w",
    encoding="utf-8",
) as f:

    json.dump(
        selected_threshold_data,
        f,
        indent=4,
    )


# ============================================================
# SAVE OVERALL SUMMARY
# ============================================================

overall_summary_file = os.path.join(
    RESULTS_OUTPUT_DIR,
    "overall_summary.json",
)

overall_summary = {
    "experiment": EXPERIMENT_NAME,
    "run": RUN_NAME,
    "input_run": RUN_04_NAME,
    "fusion_head": "A - Baseline",
    "fixed_epoch": FIXED_EPOCH,
    "number_of_oof_predictions": int(
        len(y_true)
    ),
    "healthy": int(
        np.sum(y_true == 0)
    ),
    "sick": int(
        np.sum(y_true == 1)
    ),
    "number_of_folds": int(
        len(np.unique(oof_folds))
    ),
    "overall_oof_roc_auc": float(
        overall_oof_roc_auc
    ),
    "overall_oof_pr_auc": float(
        overall_oof_pr_auc
    ),
    "minimum_sensitivity": float(
        MIN_SENSITIVITY
    ),
    "minimum_specificity": float(
        MIN_SPECIFICITY
    ),
    "valid_thresholds": int(
        len(valid_results)
    ),
    "selected_threshold": float(
        selected_threshold
    ),
    "test_set_used": False,
}


with open(
    overall_summary_file,
    "w",
    encoding="utf-8",
) as f:

    json.dump(
        overall_summary,
        f,
        indent=4,
    )


# ============================================================
# PREPARE PLOT DATA
# ============================================================

threshold_values = np.asarray(
    [
        result["threshold"]
        for result in threshold_results
    ]
)

sensitivity_values = np.asarray(
    [
        result["sensitivity"]
        for result in threshold_results
    ]
)

specificity_values = np.asarray(
    [
        result["specificity"]
        for result in threshold_results
    ]
)


# ============================================================
# PLOT 1: SENSITIVITY AND SPECIFICITY
# ============================================================

plt.figure(
    figsize=(8, 6)
)

plt.plot(
    threshold_values,
    sensitivity_values,
    label="Sensitivity",
)

plt.plot(
    threshold_values,
    specificity_values,
    label="Specificity",
)

plt.axhline(
    MIN_SENSITIVITY,
    linestyle="--",
    label="Sensitivity requirement",
)

plt.axhline(
    MIN_SPECIFICITY,
    linestyle="--",
    label="Specificity requirement",
)

plt.axvline(
    selected_threshold,
    linestyle="--",
    label=(
        f"Selected threshold = "
        f"{selected_threshold:.6f}"
    ),
)

plt.xlabel(
    "Classification threshold"
)

plt.ylabel(
    "Metric"
)

plt.title(
    "Sensitivity and Specificity "
    "vs Classification Threshold"
)

plt.ylim(
    0.0,
    1.05,
)

plt.grid(
    True,
    alpha=0.3,
)

plt.legend()

plt.tight_layout()

plt.savefig(
    os.path.join(
        PLOT_DIR,
        "sensitivity_specificity_vs_threshold.png",
    ),
    dpi=300,
)

plt.close()


# ============================================================
# PLOT 2: VALID THRESHOLDS
# ============================================================

valid_threshold_values = np.asarray(
    [
        result["threshold"]
        for result in valid_results
    ]
)

valid_sensitivity_values = np.asarray(
    [
        result["sensitivity"]
        for result in valid_results
    ]
)

valid_specificity_values = np.asarray(
    [
        result["specificity"]
        for result in valid_results
    ]
)


plt.figure(
    figsize=(8, 6)
)

plt.plot(
    valid_threshold_values,
    valid_sensitivity_values,
    label="Sensitivity",
)

plt.plot(
    valid_threshold_values,
    valid_specificity_values,
    label="Specificity",
)

plt.axhline(
    MIN_SENSITIVITY,
    linestyle="--",
    label="Sensitivity requirement",
)

plt.axhline(
    MIN_SPECIFICITY,
    linestyle="--",
    label="Specificity requirement",
)

plt.axvline(
    selected_threshold,
    linestyle="--",
    label=(
        f"Selected threshold = "
        f"{selected_threshold:.6f}"
    ),
)

plt.xlabel(
    "Classification threshold"
)

plt.ylabel(
    "Metric"
)

plt.title(
    "Thresholds Satisfying Sensitivity "
    "and Specificity Constraints"
)

plt.ylim(
    0.0,
    1.05,
)

plt.grid(
    True,
    alpha=0.3,
)

plt.legend()

plt.tight_layout()

plt.savefig(
    os.path.join(
        PLOT_DIR,
        "valid_thresholds.png",
    ),
    dpi=300,
)

plt.close()


